/** Relates an indexed line to this query for {@link QueryRelation#CONTAINS}. */
Component2D.WithinRelation relateContainsLine(ShapeField.DecodedTriangle triangle) {
  final Geometry queryGeometry = this.geometries[0];
  final Component2D query = this.queryComponent2D;
  if (queryGeometry == null) {
    throw new IllegalStateException("query geometry must not be null");
  }

  final double aLat = GeoEncodingUtils.decodeLatitude(triangle.aY);
  final double aLon = GeoEncodingUtils.decodeLongitude(triangle.aX);
